const pruneNotificationEmails = `-- name: PruneNotificationEmails :execrows
DELETE FROM notification_emails
WHERE id IN (
  SELECT e.id FROM notification_emails e
  WHERE (e.state IN ('sent', 'skipped') AND e.created_at < $1)
     OR (e.state = 'dead' AND e.created_at < $2)
  ORDER BY e.created_at
  LIMIT $3
)
`

type PruneNotificationEmailsParams struct {
	SentCutoff time.Time
	DeadCutoff time.Time
	BatchSize  int32
}

// scope: system
// No org_id on purpose: retention is install-wide.
// Sent and skipped rows older than sent_cutoff; dead rows older than dead_cutoff.
// At most batch_size rows per statement.
func (q *Queries) PruneNotificationEmails(ctx context.Context, arg PruneNotificationEmailsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneNotificationEmails, arg.SentCutoff, arg.DeadCutoff, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

