const pruneNotifications = `-- name: PruneNotifications :execrows

DELETE FROM notifications
WHERE id IN (
  SELECT n.id FROM notifications n
  WHERE n.created_at < $1
    AND (n.created_at < $2 OR n.read_at IS NOT NULL OR n.archived_at IS NOT NULL)
  ORDER BY n.created_at
  LIMIT $3
)
`

type PruneNotificationsParams struct {
	ReadCutoff time.Time
	AllCutoff  time.Time
	BatchSize  int32
}

// Retention (decisions-T13 #10). The cutoffs come from internal/notify
// (retention.go); the job (RunRetention, LAUN-44) called each query in a loop.
// Each query was one batched DELETE.
// scope: system
// No org_id on purpose: retention is install-wide.
// Read or archived rows older than read_cutoff, every row older than all_cutoff.
// Their outbox rows go by CASCADE. At most batch_size rows per statement (LAUN-44).
func (q *Queries) PruneNotifications(ctx context.Context, arg PruneNotificationsParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneNotifications, arg.ReadCutoff, arg.AllCutoff, arg.BatchSize)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

